        PyArray_TYPE(cov_array) != NPY_DOUBLE) {
        PyErr_SetString(PyExc_TypeError, "arrays must be float64");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(cov_array, 0) != n || PyArray_DIM(cov_array, 1) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix dimensions must match weights length");
        return NULL;
    }

    const double *w = (const double *)PyArray_DATA(weights_array);
    const char *cov_data = (const char *)PyArray_DATA(cov_array);
    npy_intp ws = PyArray_STRIDE(weights_array, 0) / (npy_intp)sizeof(double);
    npy_intp cov_s0 = PyArray_STRIDE(cov_array, 0);
    npy_intp cov_s1 = PyArray_STRIDE(cov_array, 1);
    npy_intp cov_s1d = cov_s1 / (npy_intp)sizeof(double);

    double *temp = (double *)malloc((size_t)n * sizeof(double));
    if (temp == NULL)
        return PyErr_NoMemory();

    for (npy_intp i = 0; i < n; i++) {
        const double *row = (const double *)(cov_data + i * cov_s0);
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; j++)
            row_sum += row[j * cov_s1d] * w[j * ws];
        temp[i] = row_sum;
    }

    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; i++)
        risk_squared += w[i * ws] * temp[i];

    free(temp);

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array, *returns_array;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &returns_array))
        return NULL;

    if (PyArray_NDIM(weights_array) != 1 || PyArray_NDIM(returns_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "inputs must be 1D arrays");
        return NULL;
