        PyArray_TYPE(returns_array) != NPY_DOUBLE) {
        PyErr_SetString(PyExc_TypeError, "arrays must be float64");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    const double *w = (const double *)PyArray_DATA(weights_array);
    const double *r = (const double *)PyArray_DATA(returns_array);
    npy_intp ws = PyArray_STRIDE(weights_array, 0) / (npy_intp)sizeof(double);
    npy_intp rs = PyArray_STRIDE(returns_array, 0) / (npy_intp)sizeof(double);

    double total_return = 0.0;
    for (npy_intp i = 0; i < n; i++)
        total_return += w[i * ws] * r[i * rs];

    return PyFloat_FromDouble(total_return);
}

