/*
 * High-performance portfolio calculations using a C extension.
 *
 * Fast paths use zero-copy NumPy buffer access. Plain Python sequences are
 * consumed directly, avoiding the cost of materializing a large temporary
 * matrix just to pass it to C.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static int fill_double_sequence(PyObject *obj, double *buf, npy_intp expect) {
    PyObject *fast = PySequence_Fast(obj, "expected a sequence");
    if (fast == NULL)
        return 0;

    Py_ssize_t m = PySequence_Fast_GET_SIZE(fast);
    if (m != (Py_ssize_t)expect) {
        Py_DECREF(fast);
        PyErr_SetString(PyExc_ValueError, "sequence has unexpected length");
        return 0;
    }

    PyObject **items = PySequence_Fast_ITEMS(fast);
    for (Py_ssize_t k = 0; k < m; k++) {
        PyObject *item = items[k];
        if (PyFloat_CheckExact(item)) {
            buf[k] = PyFloat_AS_DOUBLE(item);
        } else {
            double v = PyFloat_AsDouble(item);
            if (v == -1.0 && PyErr_Occurred()) {
                Py_DECREF(fast);
                return 0;
            }
            buf[k] = v;
        }
    }

    Py_DECREF(fast);
    return 1;
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    npy_intp n;
    int weight_is_array = PyArray_Check(weights_obj);
    int cov_is_array = PyArray_Check(cov_obj);

    if (weight_is_array) {
        PyArrayObject *a = (PyArrayObject *)weights_obj;
        if (PyArray_NDIM(a) != 1 || PyArray_TYPE(a) != NPY_DOUBLE) {
            PyErr_SetString(PyExc_TypeError,
                            "weights array must be 1D float64");
            return NULL;
        }
        n = PyArray_DIM(a, 0);
    } else {
        Py_ssize_t len = PyObject_Length(weights_obj);
        if (len < 0)
            return NULL;
        n = (npy_intp)len;
    }

    if (cov_is_array) {
        PyArrayObject *a = (PyArrayObject *)cov_obj;
        if (PyArray_NDIM(a) != 2 || PyArray_TYPE(a) != NPY_DOUBLE ||
            PyArray_DIM(a, 0) != n || PyArray_DIM(a, 1) != n) {
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix must be an NxN float64 array");
            return NULL;
        }
    } else {
        Py_ssize_t rows = PyObject_Length(cov_obj);
        if (rows < 0)
            return NULL;
        if (rows != (Py_ssize_t)n) {
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix dimensions must match weights length");
            return NULL;
        }
    }

    double *temp = (double *)malloc((size_t)n * sizeof(double));
    if (temp == NULL)
        return PyErr_NoMemory();

    double risk_squared = 0.0;

    if (weight_is_array && cov_is_array) {
        PyArrayObject *wa = (PyArrayObject *)weights_obj;
        PyArrayObject *ca = (PyArrayObject *)cov_obj;
        const double *w = (const double *)PyArray_DATA(wa);
        const char *cov_data = (const char *)PyArray_DATA(ca);
        npy_intp ws = PyArray_STRIDE(wa, 0) / (npy_intp)sizeof(double);
        npy_intp cov_s0 = PyArray_STRIDE(ca, 0);
        npy_intp cov_s1d = PyArray_STRIDE(ca, 1) / (npy_intp)sizeof(double);

        for (npy_intp i = 0; i < n; i++) {
            const double *row = (const double *)(cov_data + i * cov_s0);
            double row_sum = 0.0;
            for (npy_intp j = 0; j < n; j++)
                row_sum += row[j * cov_s1d] * w[j * ws];
            temp[i] = row_sum;
        }

        for (npy_intp i = 0; i < n; i++)
            risk_squared += w[i * ws] * temp[i];
    } else {
        double *w = (double *)malloc((size_t)n * sizeof(double));
        double *row = (double *)malloc((size_t)n * sizeof(double));
        if (w == NULL || row == NULL) {
            free(w);
            free(row);
            free(temp);
            return PyErr_NoMemory();
        }

        int ok;
        if (weight_is_array) {
            PyArrayObject *wa = (PyArrayObject *)weights_obj;
            const double *src = (const double *)PyArray_DATA(wa);
            npy_intp ws = PyArray_STRIDE(wa, 0) / (npy_intp)sizeof(double);
            for (npy_intp i = 0; i < n; i++)
                w[i] = src[i * ws];
            ok = 1;
        } else {
            ok = fill_double_sequence(weights_obj, w, n);
        }

        if (ok) {
            for (npy_intp i = 0; i < n; i++) {
                PyObject *row_obj;
                int new_ref = 0;
                if (PyList_Check(cov_obj)) {
                    row_obj = PyList_GET_ITEM(cov_obj, i);
                } else if (PyTuple_Check(cov_obj)) {
                    row_obj = PyTuple_GET_ITEM(cov_obj, i);
                } else {
                    row_obj = PySequence_GetItem(cov_obj, i);
                    if (row_obj == NULL) {
                        ok = 0;
                        break;
                    }
                    new_ref = 1;
                }

                ok = fill_double_sequence(row_obj, row, n);
                if (new_ref)
                    Py_DECREF(row_obj);
                if (!ok)
                    break;

                double row_sum = 0.0;
                for (npy_intp j = 0; j < n; j++)
                    row_sum += row[j] * w[j];
                temp[i] = row_sum;
            }
        }

        if (ok) {
            for (npy_intp i = 0; i < n; i++)
                risk_squared += w[i] * temp[i];
        }

        free(w);
        free(row);
        if (!ok) {
            free(temp);
            return NULL;
        }
    }

    free(temp);
    return PyFloat_FromDouble(sqrt(risk_squared));
}

